package cn.longer233.gamenarrator.creative;
import com.fasterxml.jackson.databind.*; import java.net.*; import java.net.http.*; import java.time.*; import java.util.*;
final class ComfyUiImageClient {
 private final ObjectMapper mapper; private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).build(); private final URI base;
 ComfyUiImageClient(ObjectMapper m,String endpoint){mapper=m;base=URI.create(endpoint.replaceAll("/$","")+"/");}
 byte[] generate(String model,String prompt,String negative,int width,int height,int steps,long seed) throws Exception {
  String ck=mapper.writeValueAsString(Map.of("1",Map.of("class_type","CheckpointLoaderSimple","inputs",Map.of("ckpt_name",model)),"2",Map.of("class_type","CLIPTextEncode","inputs",Map.of("text",prompt,"clip",List.of("1",1))),"3",Map.of("class_type","CLIPTextEncode","inputs",Map.of("text",negative,"clip",List.of("1",1))),"4",Map.of("class_type","EmptyLatentImage","inputs",Map.of("width",width,"height",height,"batch_size",1)),"5",Map.of("class_type","KSampler","inputs",Map.of("seed",seed,"steps",steps,"cfg",6.5,"sampler_name","euler","scheduler","normal","denoise",1.0,"model",List.of("1",0),"positive",List.of("2",0),"negative",List.of("3",0),"latent_image",List.of("4",0))),"6",Map.of("class_type","VAEDecode","inputs",Map.of("samples",List.of("5",0),"vae",List.of("1",2))),"7",Map.of("class_type","SaveImage","inputs",Map.of("filename_prefix","game-narrator","images",List.of("6",0)))));
  String client=UUID.randomUUID().toString(); HttpRequest q=HttpRequest.newBuilder(base.resolve("prompt")).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(mapper.writeValueAsString(Map.of("prompt",mapper.readTree(ck),"client_id",client)))).build(); JsonNode p=mapper.readTree(http.send(q,HttpResponse.BodyHandlers.ofString()).body()); String id=p.path("prompt_id").asText(); if(id.isBlank()) throw new IllegalStateException("ComfyUI 未接受工作流："+p);
  for(int i=0;i<120;i++){Thread.sleep(1000); JsonNode h=mapper.readTree(http.send(HttpRequest.newBuilder(base.resolve("history/"+id)).GET().build(),HttpResponse.BodyHandlers.ofString()).body()).path(id); if(h.isMissingNode()) continue; JsonNode images=h.path("outputs").findValue("images"); if(images!=null&&images.isArray()&&images.size()>0){JsonNode im=images.get(0); String u="view?filename="+URLEncoder.encode(im.path("filename").asText(),"UTF-8")+"&subfolder="+URLEncoder.encode(im.path("subfolder").asText(),"UTF-8")+"&type="+URLEncoder.encode(im.path("type").asText("output"),"UTF-8"); return http.send(HttpRequest.newBuilder(base.resolve(u)).GET().build(),HttpResponse.BodyHandlers.ofByteArray()).body();}}
  throw new IllegalStateException("ComfyUI 生成超时");
 }
}
